types.effect='特效';icons.fx='M12 3l2.4 6.6L21 12l-6.6 2.4L12 21l-2.4-6.6L3 12l6.6-2.4z';typeIcons.effect='fx';
function visualEffectFields(value={},editing=false){const v=KotobaCore.effectSettings(value),attr=key=>editing?`data-vfx="${key}"`:`name="${key}"`;return `<div class="field"><label>特效类型</label><select ${attr('effect')}>${optionList(KotobaCore.visualEffects,v.effect)}</select></div><div class="field-row"><div class="field"><label>持续时间（毫秒）</label><input type="number" min="100" max="5000" step="100" value="${v.duration}" ${attr('duration')}></div><div class="field"><label>强度（1–100）</label><input type="number" min="1" max="100" value="${v.intensity}" ${attr('intensity')}></div></div><div class="field-row"><div class="field"><label>闪光颜色</label><input type="color" value="${v.color}" ${attr('color')}></div><div class="field"><label>播放结束后</label><select ${attr('advance')}><option value="auto" ${v.advance==='auto'?'selected':''}>自动继续剧情</option><option value="click" ${v.advance==='click'?'selected':''}>等待点击</option></select></div></div><p class="field-note">画面抖动作用于背景、CG 和独立立绘；立绘抖动只作用于当前独立立绘。CG 中的人物无法单独抖动。闪光为单次闪入淡出。</p>`}
function insertVisualEffect(){dialog('插入特效',visualEffectFields({effect:'flash',duration:600,intensity:70}),'插入特效',f=>{change(()=>{const values=KotobaCore.effectSettings(Object.fromEntries(f));const b={id:uid(),type:'effect',...values,text:KotobaCore.visualEffects[values.effect]};const i=scene().blocks.findIndex(b=>b.id===selected);scene().blocks.splice(i<0?scene().blocks.length:i+1,0,b);selected=b.id;view='script';mode='visual';stopContentPlayback()})})}
function makeStageEffectCompletion(projectId,sid,index,blockId){const current=()=>playing&&!ended&&project.id===projectId&&playScene===sid&&playIndex===index&&project.scenes.find(s=>s.id===sid)?.blocks[index]?.id===blockId;const finish=()=>{if(!current())return;if($('#modal').open){setTimeout(finish,60);return}advance()};return finish}
const vfxDraw=draw,vfxInspector=drawInspector,vfxValidate=validateProject;
draw=function(){vfxDraw();if(view!=='script')return;$('.block-footer')?.insertAdjacentHTML('beforeend',`<button class="btn small" data-action="insert-vfx">${ic('fx')} 特效</button>`);for(const b of scene().blocks)if(b.type==='effect'){const row=Array.from(document.querySelectorAll('.block')).find(el=>el.dataset.id===b.id),v=KotobaCore.effectSettings(b);if(row?.querySelector('.block-text'))row.querySelector('.block-text').textContent=`${KotobaCore.visualEffects[v.effect]} · ${v.duration}ms · 强度 ${v.intensity}`}};
drawInspector=function(){vfxInspector();if(block()?.type==='effect')$('#inspector').insertAdjacentHTML('afterbegin',visualEffectFields(block(),true)+'<button class="btn small" data-action="replay-vfx">重播特效</button>')};
validateProject=function(p){vfxValidate(p);for(const s of p.scenes)for(const b of s.blocks)if(b.type==='effect'){if(!Object.hasOwn(KotobaCore.visualEffects,b.effect))throw Error('不支持的特效类型');if(b.duration!==undefined&&(!Number.isFinite(Number(b.duration))||Number(b.duration)<100||Number(b.duration)>5000))throw Error('特效时长须为 100–5000 毫秒');if(b.intensity!==undefined&&(!Number.isFinite(Number(b.intensity))||Number(b.intensity)<1||Number(b.intensity)>100))throw Error('特效强度须为 1–100');if(b.color!==undefined&&!/^#[a-f\d]{6}$/i.test(b.color))throw Error('特效颜色格式无效');if(b.advance!==undefined&&!['auto','click'].includes(b.advance))throw Error('特效继续方式无效')}return p};
document.addEventListener('click',e=>{const a=e.target.closest('[data-action]')?.dataset.action;if(!['insert-vfx','replay-vfx'].includes(a))return;e.preventDefault();e.stopImmediatePropagation();if(a==='insert-vfx')insertVisualEffect();else drawStage(true)},true);
document.addEventListener('change',e=>{const key=e.target.dataset.vfx;if(!key||block()?.type!=='effect')return;change(()=>{block()[key]=['duration','intensity'].includes(key)?Number(e.target.value):e.target.value;Object.assign(block(),KotobaCore.effectSettings(block()))})});
draw();
